// Surah 36 - 83 verses (auto-generated)
import type { VerseText } from "./verses";

const yaseen: VerseText[] = [
  { surahNumber: 36, verseNumber: 1, arabic: "يسٓ", translation: "Yã-Sĩn.", tafsir: "حروف مقطعة في فاتحة السورة، من أسرار القرآن التي استأثر الله بعلمها." },
  { surahNumber: 36, verseNumber: 2, arabic: "وَالْقُرْآنِ الْحَكِيمِ", translation: "By the Quran, rich in wisdom!", tafsir: "قسم بالقرآن الحكيم المحكم الذي لا يأتيه الباطل." },
  { surahNumber: 36, verseNumber: 3, arabic: "إِنَّكَ لَمِنَ الْمُرْسَلِينَ", translation: "You are truly one of the messengers,", tafsir: "إثبات النبوة للرسول صلى الله عليه وسلم." },
  { surahNumber: 36, verseNumber: 4, arabic: "عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ", translation: "upon the Straight Path.", tafsir: "على طريق مستقيم لا اعوجاج فيه." },
  { surahNumber: 36, verseNumber: 5, arabic: "تَنزِيلَ الْعَزِيزِ الرَّحِيمِ", translation: "A revelation from the Almighty, Most Merciful,", tafsir: "هذا القرآن منزل من الله العزيز في ملكه الرحيم بخلقه." },
  { surahNumber: 36, verseNumber: 6, arabic: "لِتُنذِرَ قَوْمًا مَّا أُنذِرَ آبَاؤُهُمْ فَهُمْ غَافِلُونَ", translation: "so that you may warn a people whose ancestors were not warned, and so are heedless.", tafsir: "لتنذر العرب وهم أميون لم يُنذر آباؤهم من قبل." },
  { surahNumber: 36, verseNumber: 7, arabic: "لَقَدْ حَقَّ الْقَوْلُ عَلَىٰ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ", translation: "Indeed, the decree of torment has overtaken most of them, for they do not believe.", tafsir: "سبق العلم الإلهي بأن أكثرهم لا يؤمنون." },
  { surahNumber: 36, verseNumber: 8, arabic: "إِنَّا جَعَلْنَا فِي أَعْنَاقِهِمْ أَغْلَالًا فَهِيَ إِلَى الْأَذْقَانِ فَهُم مُّقْمَحُونَ", translation: "It is We who have placed collars around their necks up to their chins so their heads are forced up.", tafsir: "مثل لكونهم ممنوعين من الإيمان كمن غُلّت يداه إلى عنقه فرفع رأسه." },
  { surahNumber: 36, verseNumber: 9, arabic: "وَجَعَلْنَا مِن بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ", translation: "And We have placed a barrier before and behind them, covering them so they fail to see.", tafsir: "تمثيل لإعراضهم عن الإيمان فصاروا كالمسدود عنهم." },
  { surahNumber: 36, verseNumber: 10, arabic: "وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", translation: "It is the same whether you warn them or not: they will not believe.", tafsir: "استغرقهم الشقاء فلا ينفعهم الإنذار." },
  { surahNumber: 36, verseNumber: 11, arabic: "إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشَى الرَّحْمَٰنَ بِالْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ", translation: "You can only warn whoever follows this Quran and fears the Most Compassionate without seeing Him. So give them good news of forgiveness and a noble reward.", tafsir: "نافع إنذارك لمن اتبع القرآن وخشي الله في الغيب." },
  { surahNumber: 36, verseNumber: 12, arabic: "إِنَّا نَحْنُ نُحْيِي الْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ ۚ وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُّبِينٍ", translation: "Surely We alone bring the dead back to life and record what deeds they send ahead and leave behind. Everything is kept in an evident Record.", tafsir: "إثبات البعث، وأن الله يكتب أعمال العباد وأثرهم في الدنيا." },
  { surahNumber: 36, verseNumber: 13, arabic: "وَاضْرِبْ لَهُم مَّثَلًا أَصْحَابَ الْقَرْيَةِ إِذْ جَاءَهَا الْمُرْسَلُونَ", translation: "Compare them to the people of a town to whom messengers came,", tafsir: "ضرب مثل لمكة بما جرى لأهل أنطاكية مع رسل عيسى." },
  { surahNumber: 36, verseNumber: 14, arabic: "إِذْ أَرْسَلْنَا إِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوا إِنَّا إِلَيْكُم مُّرْسَلُونَ", translation: "We sent them two messengers, but they rejected both. So We reinforced them with a third. They declared: We have indeed been sent to you.", tafsir: "قصة أصحاب القرية الذين أُرسل إليهم رسلان فكذبوهما، فأيدوا بثالث." },
  { surahNumber: 36, verseNumber: 15, arabic: "قَالُوا مَا أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَا أَنزَلَ الرَّحْمَٰنُ مِن شَيْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ", translation: "They replied: You are only humans like us! The Most Compassionate has revealed nothing. You are only lying.", tafsir: "جحد أهل القرية نبوة الرسل بحجة أنهم بشر." },
  { surahNumber: 36, verseNumber: 16, arabic: "قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ", translation: "They responded: Our Lord knows that we have indeed been sent to you.", tafsir: "أقسم الرسل أنهم مرسلون، وعلم الله يشهد بذلك." },
  { surahNumber: 36, verseNumber: 17, arabic: "وَمَا عَلَيْنَا إِلَّا الْبَلَاغُ الْمُبِينُ", translation: "Our duty is only to deliver the message clearly.", tafsir: "ليس علينا إلا البلاغ، والهداية بيد الله." },
  { surahNumber: 36, verseNumber: 18, arabic: "قَالُوا إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِن لَّمْ تَنتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ", translation: "They replied: We consider you a bad omen. If you do not stop, we will surely stone you to death, and you will suffer a painful punishment from us.", tafsir: "تشاؤم أهل القرية بالرسل وتهديدهم بالرجم." },
  { surahNumber: 36, verseNumber: 19, arabic: "قَالُوا طَائِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ", translation: "The messengers said: Your bad omen lies within yourselves. Are you saying this because you were reminded of the truth? No! You are a transgressing people.", tafsir: "الرسل يبينون أن الشؤم من أعمالهم لا من الرسل." },
  { surahNumber: 36, verseNumber: 20, arabic: "وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَا قَوْمِ اتَّبِعُوا الْمُرْسَلِينَ", translation: "Then a man came running from the farthest part of the city, crying: My people! Follow the messengers.", tafsir: "مجيء حبيب النجار مؤمناً من أقصى المدينة يدعو قومه لاتباع الرسل." },
  { surahNumber: 36, verseNumber: 21, arabic: "اتَّبِعُوا مَن لَّا يَسْأَلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ", translation: "Follow those who ask no reward of you, and are rightly guided.", tafsir: "وصف الرسل بأنهم لا يطلبون أجراً وعلى هدى." },
  { surahNumber: 36, verseNumber: 22, arabic: "وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي وَإِلَيْهِ تُرْجَعُونَ", translation: "It would not be right for me not to worship the One Who created me, and to Whom you will all be returned.", tafsir: "الحجة أن الله هو الخالق وإليه المرجع فحقه العبادة." },
  { surahNumber: 36, verseNumber: 23, arabic: "أَأَتَّخِذُ مِن دُونِهِ آلِهَةً إِن يُرِدْنِ الرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّي شَفَاعَتُهُمْ شَيْئًا وَلَا يُنقِذُونَ", translation: "How could I take other gods instead of Him? If the Most Compassionate intended to harm me, their intercession would be of no use whatsoever, nor could they save me.", tafsir: "بطلان عبادة غير الله لأنها لا تنفع ولا تضر." },
  { surahNumber: 36, verseNumber: 24, arabic: "إِنِّي إِذًا لَّفِي ضَلَالٍ مُّبِينٍ", translation: "In that case I would truly be in clear error.", tafsir: "لو عبدت غير الله لكنت في ضلال واضح." },
  { surahNumber: 36, verseNumber: 25, arabic: "إِنِّي آمَنتُ بِرَبِّكُمْ فَاسْمَعُونِ", translation: "Indeed, I believe in your Lord, so listen to me.", tafsir: "إيمان حبيب النجار وجهاره بالحق." },
  { surahNumber: 36, verseNumber: 26, arabic: "قِيلَ ادْخُلِ الْجَنَّةَ ۖ قَالَ يَا لَيْتَ قَوْمِي يَعْلَمُونَ", translation: "He was told: Enter Paradise! He said: If only my people knew…", tafsir: "كرامة الله لمؤمن آل يس بدخوله الجنة، وتمنيه علم قومه بما هو فيه من النعيم." },
  { surahNumber: 36, verseNumber: 27, arabic: "بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ", translation: "how my Lord has forgiven me, and made me one of the honourable ones!", tafsir: "سبب تمنيه: شكراً لله على مغفرته وإكرامه." },
  { surahNumber: 36, verseNumber: 28, arabic: "وَمَا أَنزَلْنَا عَلَىٰ قَوْمِهِ مِن بَعْدِهِ مِن جُندٍ مِّنَ السَّمَاءِ وَمَا كُنَّا مُنزِلِينَ", translation: "We did not send any soldiers from heaven against his people after his death, nor do We need to send any.", tafsir: "ما احتاج الله إلى جند من السماء لإهلاك قومه." },
  { surahNumber: 36, verseNumber: 29, arabic: "إِن كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ", translation: "It only took one Blast, and then they were silent.", tafsir: "أهلكوا بصيحة واحدة فماتوا جميعاً." },
  { surahNumber: 36, verseNumber: 30, arabic: "يَا حَسْرَةً عَلَى الْعِبَادِ ۚ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ", translation: "Alas for wrongdoing servants! No messenger ever came to them without being mocked.", tafsir: "تحسر على العباد لاستهزائهم بالرسل." },
  { surahNumber: 36, verseNumber: 31, arabic: "أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ الْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ", translation: "Do they not see how many generations We destroyed before them, who will never return to them?", tafsir: "تذكير بإهلاك الأمم السابقة وعدم رجوعها." },
  { surahNumber: 36, verseNumber: 32, arabic: "وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ", translation: "But each and every one of them will be brought before Us.", tafsir: "جميع الأمم محشورة إلى الله للحساب." },
  { surahNumber: 36, verseNumber: 33, arabic: "وَآيَةٌ لَّهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَاهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ", translation: "A sign for them is the dead earth: We bring it back to life, producing grain from which they eat.", tafsir: "الاستدلال على البعث بإحياء الأرض الميتة." },
  { surahNumber: 36, verseNumber: 34, arabic: "وَجَعَلْنَا فِيهَا جَنَّاتٍ مِّن نَّخِيلٍ وَأَعْنَابٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ", translation: "We place in it gardens of palm trees and grapevines, and cause springs to gush forth,", tafsir: "نعمة الله في خلق الجنات والعيون." },
  { surahNumber: 36, verseNumber: 35, arabic: "لِيَأْكُلُوا مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ ۖ أَفَلَا يَشْكُرُونَ", translation: "so that they may eat from its fruit, which their own hands did not produce. Will they not then give thanks?", tafsir: "التذكير بنعمة الأكل من ثمار لم يتعبوا فيها." },
  { surahNumber: 36, verseNumber: 36, arabic: "سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا مِمَّا تُنبِتُ الْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ", translation: "Glory be to the One Who created all things in pairs—be it what the earth produces, their own kind, or what they do not know.", tafsir: "تنزيه الله على خلق الأزواج في النبات والحيوان وغيرها." },
  { surahNumber: 36, verseNumber: 37, arabic: "وَآيَةٌ لَّهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ فَإِذَا هُم مُّظْلِمُونَ", translation: "Another sign for them is the night: We strip daylight from it, leaving them in darkness.", tafsir: "آية في تعاقب الليل والنهار." },
  { surahNumber: 36, verseNumber: 38, arabic: "وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ", translation: "The sun travels toward its destination. Such is the design of the Almighty, the All-Knowing.", tafsir: "آية في جريان الشمس لمستقرها بتقدير الله." },
  { surahNumber: 36, verseNumber: 39, arabic: "وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ الْقَدِيمِ", translation: "And the moon—We have determined its phases, until it returns to its initial state, like an old, curved date stalk.", tafsir: "آية في منازل القمر حتى يصير كالعذق القديم." },
  { surahNumber: 36, verseNumber: 40, arabic: "لَا الشَّمْسُ يَنبَغِي لَهَا أَن تُدْرِكَ الْقَمَرَ وَلَا اللَّيْلُ سَابِقُ النَّهَارِ ۚ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ", translation: "It is not for the sun to catch up with the moon, nor does the night outstrip the day. Each is travelling in an orbit of their own.", tafsir: "لكل من الشمس والقمر والكواكب فلكها الذي تجري فيه." },
  { surahNumber: 36, verseNumber: 41, arabic: "وَآيَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ", translation: "It is a sign for them that We carried their descendants with Noah in the fully loaded Ark,", tafsir: "آية في حمل ذرية آدم في سفينة نوح." },
  { surahNumber: 36, verseNumber: 42, arabic: "وَخَلَقْنَا لَهُم مِّن مِّثْلِهِ مَا يَرْكَبُونَ", translation: "and created for them things similar to ride.", tafsir: "خلق الله للناس من المراكب مثل سفينة نوح." },
  { surahNumber: 36, verseNumber: 43, arabic: "وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ", translation: "If We willed, We could drown them: there would be no response to their cries, nor would they be saved,", tafsir: "قدرة الله على إغراقهم لو شاء." },
  { surahNumber: 36, verseNumber: 44, arabic: "إِلَّا رَحْمَةً مِّنَّا وَمَتَاعًا إِلَىٰ حِينٍ", translation: "except by mercy from Us and as a provision for a while.", tafsir: "إلا رحمة من الله بقاءً إلى انقضاء الآجال." },
  { surahNumber: 36, verseNumber: 45, arabic: "وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ", translation: "When it is said to them: Beware of what is ahead of you and what is behind you, so you may be given mercy, they turn away.", tafsir: "أمر المشركين بالتقوى في الدنيا والآخرة لينالوا الرحمة." },
  { surahNumber: 36, verseNumber: 46, arabic: "وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ", translation: "Whenever a sign comes to them from their Lord, they turn away from it.", tafsir: "إعراضهم عن كل آية تأتيهم." },
  { surahNumber: 36, verseNumber: 47, arabic: "وَإِذَا قِيلَ لَهُمْ أَنفِقُوا مِمَّا رَزَقَكُمُ اللَّهُ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَنُطْعِمُ مَن لَّوْ يَشَاءُ اللَّهُ أَطْعَمَهُ إِنْ أَنتُمْ إِلَّا فِي ضَلَالٍ مُّبِينٍ", translation: "And when it is said to them: Donate from what Allah has provided for you, the disbelievers say to the believers: Why should we feed those whom Allah could have fed if He wanted to? You are clearly astray!", tafsir: "امتنان الكفار عن الإطعام بزعم أن الله يرزق من يشاء." },
  { surahNumber: 36, verseNumber: 48, arabic: "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ", translation: "And they ask the believers: When will this promise be fulfilled, if what you say is true?", tafsir: "استعجال المشركين للبعث استبعاداً له." },
  { surahNumber: 36, verseNumber: 49, arabic: "مَا يَنظُرُونَ إِلَّا صَيْحَةً وَاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ", translation: "They only wait for a single Blast, which will seize them while they are disputing.", tafsir: "ما ينتظرون إلا نفخة الصور تأخذهم وهم يتخاصمون في أسواقهم." },
  { surahNumber: 36, verseNumber: 50, arabic: "فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَا إِلَىٰ أَهْلِهِمْ يَرْجِعُونَ", translation: "They will not be able to make a bequest, nor return to their families.", tafsir: "سرعة البعث وأنهم يُبغتون فلا يوصون ولا يرجعون." },
  { surahNumber: 36, verseNumber: 51, arabic: "وَنُفِخَ فِي الصُّورِ فَإِذَا هُم مِّنَ الْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ", translation: "The Trumpet will be blown, and then—behold!—they will all rush from their graves to their Lord.", tafsir: "النفخة الثانية يقوم الناس من القبور إلى ربهم." },
  { surahNumber: 36, verseNumber: 52, arabic: "قَالُوا يَا وَيْلَنَا مَن بَعَثَنَا مِن مَّرْقَدِنَا ۜ هَٰذَا مَا وَعَدَ الرَّحْمَٰنُ وَصَدَقَ الْمُرْسَلُونَ", translation: "They will cry: Oh, woe to us! Who has raised us from our place of sleep? The response will be: This is what the Most Compassionate had promised, and the messengers told the truth.", tafsir: "قول الكفار عند البعث وتذكيرهم بما وعدهم به الرسل." },
  { surahNumber: 36, verseNumber: 53, arabic: "إِن كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ", translation: "It will only take one Blast, and then they will all be brought before Us.", tafsir: "سهولة البعث، صيحة واحدة فيحشرون." },
  { surahNumber: 36, verseNumber: 54, arabic: "فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْئًا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ", translation: "Today no soul will be wronged in the least, and you will only be rewarded for what you used to do.", tafsir: "عدل الله يوم القيامة لا يُظلم أحد ولا يُجازى إلا بعمله." },
  { surahNumber: 36, verseNumber: 55, arabic: "إِنَّ أَصْحَابَ الْجَنَّةِ الْيَوْمَ فِي شُغُلٍ فَاكِهُونَ", translation: "Surely the residents of Paradise will be fully occupied with bliss today.", tafsir: "حال أهل الجنة في النعيم والفرح." },
  { surahNumber: 36, verseNumber: 56, arabic: "هُمْ وَأَزْوَاجُهُمْ فِي ظِلَالٍ عَلَى الْأَرَائِكِ مُتَّكِئُونَ", translation: "They and their spouses will be in cool shade, reclining on canopied couches.", tafsir: "تنعمهم مع أزواجهم في ظلال الجنة." },
  { surahNumber: 36, verseNumber: 57, arabic: "لَهُمْ فِيهَا فَاكِهَةٌ وَلَهُم مَّا يَدَّعُونَ", translation: "There they will have fruits and whatever they desire,", tafsir: "لهم في الجنة فاكهة وكل ما يطلبون." },
  { surahNumber: 36, verseNumber: 58, arabic: "سَلَامٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ", translation: "and they will be greeted with: Peace, a word from a Lord Most Merciful.", tafsir: "تحية الله لأهل الجنة بالسلام." },
  { surahNumber: 36, verseNumber: 59, arabic: "وَامْتَازُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ", translation: "But He will say: Stand apart from the believers today, O wicked ones!", tafsir: "أمر الله للمجرمين بالتميز عن المؤمنين." },
  { surahNumber: 36, verseNumber: 60, arabic: "أَلَمْ أَعْهَدْ إِلَيْكُمْ يَا بَنِي آدَمَ أَن لَّا تَعْبُدُوا الشَّيْطَانَ ۖ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ", translation: "Did I not command you, O children of Adam, not to worship Satan, for he is truly your sworn enemy?", tafsir: "تذكير الله لبني آدم بعهده ألا يعبدوا الشيطان." },
  { surahNumber: 36, verseNumber: 61, arabic: "وَأَنِ اعْبُدُونِي هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ", translation: "and that you must worship Me alone? This is the Straight Path.", tafsir: "أمر الله بعبادته وحده وأنها هي الطريق المستقيم." },
  { surahNumber: 36, verseNumber: 62, arabic: "وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا ۖ أَفَلَمْ تَكُونُوا تَعْقِلُونَ", translation: "Yet he has already led so many of you astray. Did you not have any sense?", tafsir: "تذكير بإضلال الشيطان لكثير من الناس." },
  { surahNumber: 36, verseNumber: 63, arabic: "هَٰذِهِ جَهَنَّمُ الَّتِي كُنتُمْ تُوعَدُونَ", translation: "This is the Hell you were promised.", tafsir: "تعريرهم على جهنم التي كان الرسل يوعدونهم بها." },
  { surahNumber: 36, verseNumber: 64, arabic: "اصْلَوْهَا الْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ", translation: "Burn in it today, because you persistently denied the truth.", tafsir: "أمرهم بدخول النار جزاء كفرهم." },
  { surahNumber: 36, verseNumber: 65, arabic: "الْيَوْمَ نَخْتِمُ عَلَىٰ أَفْوَاهِهِمْ وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا يَكْسِبُونَ", translation: "Today We will seal their mouths, their hands will speak to Us, and their feet will testify to what they used to commit.", tafsir: "في الآخرة تُختم الأفواه وتشهد الجوارح بأعمال أصحابها." },
  { surahNumber: 36, verseNumber: 66, arabic: "وَلَوْ نَشَاءُ لَطَمَسْنَا عَلَىٰ أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَأَنَّىٰ يُبْصِرُونَ", translation: "If it had been Our Will, We could have easily blinded their eyes, so they would struggle to find their way. How then could they see?", tafsir: "لو شاء الله لطمس على أعينهم فما أبصروا الطريق." },
  { surahNumber: 36, verseNumber: 67, arabic: "وَلَوْ نَشَاءُ لَمَسَخْنَاهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ", translation: "And if it had been Our Will, We could have easily deformed them in place, leaving them unable to walk or return.", tafsir: "قدرة الله على مسخهم في أماكنهم فلا يقدرون على الحركة." },
  { surahNumber: 36, verseNumber: 68, arabic: "وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ", translation: "And whoever We grant long life, We reverse their development. Do they not then understand?", tafsir: "من أطال الله عمره ردّه إلى أرذل العمر ضعيفاً." },
  { surahNumber: 36, verseNumber: 69, arabic: "وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنبَغِي لَهُ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْآنٌ مُّبِينٌ", translation: "We have not magically taught the Prophet poetry, nor does it suit him. This revelation is simply a reminder and a clear Quran,", tafsir: "تنزيه النبي عن الشعر، فالقرآن ذكر وبيان لا شعر." },
  { surahNumber: 36, verseNumber: 70, arabic: "لِيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِينَ", translation: "to warn whoever is truly alive, and for the word of torment to be proven against the disbelievers.", tafsir: "القرآن إنذار لأهل القلوب الحية، وإلزام للحجة على الكافرين." },
  { surahNumber: 36, verseNumber: 71, arabic: "أَلَمْ يَرَوْا أَنَّا خَلَقْنَا لَهُم مِمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا فَهُمْ لَهَا مَالِكُونَ", translation: "Do they not see that We have created for them—among what Our Hands have fashioned—cattle they own?", tafsir: "تذكير بنعمة خلق الأنعام وتسخيرها لهم." },
  { surahNumber: 36, verseNumber: 72, arabic: "وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ", translation: "And We have subjected them cattle to them, so some they ride and some they eat.", tafsir: "تسخير الأنعام للركوب والأكل." },
  { surahNumber: 36, verseNumber: 73, arabic: "وَلَهُمْ فِيهَا مَنَافِعُ وَمَشَارِبُ ۖ أَفَلَا يَشْكُرُونَ", translation: "And they have other benefits and drinks in them. Will they not then give thanks?", tafsir: "منافع الأنعام وألبانها، أفلا يشكرون المنعم؟" },
  { surahNumber: 36, verseNumber: 74, arabic: "وَاتَّخَذُوا مِن دُونِ اللَّهِ آلِهَةً لَّعَلَّهُمْ يُنصَرُونَ", translation: "Yet they have taken gods other than Allah, hoping to receive help from them.", tafsir: "اتخاذهم آلهة من دون الله رجاء نصرها." },
  { surahNumber: 36, verseNumber: 75, arabic: "لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ", translation: "They cannot help them, even though their false gods are mobilized as soldiers ready for battle.", tafsir: "عجز الآلهة عن نصرهم مع أنها محضورة معهم." },
  { surahNumber: 36, verseNumber: 76, arabic: "فَلَا يَحْزُنكَ قَوْلُهُمْ ۖ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", translation: "So do not let their words grieve you O Prophet. We certainly know what they conceal and what they reveal.", tafsir: "تعزية للنبي صلى الله عليه وسلم بأقوال قومه." },
  { surahNumber: 36, verseNumber: 77, arabic: "أَوَلَمْ يَرَ الْإِنسَانُ أَنَّا خَلَقْنَاهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ", translation: "Does man not see that We created him from a drop of fluid, yet he openly challenges Us?", tafsir: "تعجيب من جدال الإنسان مع أن الله خلقه من نطفة." },
  { surahNumber: 36, verseNumber: 78, arabic: "وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ ۖ قَالَ مَن يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ", translation: "He compares Us to others, forgetting his own origin, saying: Who can give life to bones after they have decayed?", tafsir: "أنكار المنكر للبعث مع نسيانه خلقه من عدم." },
  { surahNumber: 36, verseNumber: 79, arabic: "قُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ", translation: "Say, O Prophet: He Who created them in the first place will bring them back to life. And He has full knowledge of His entire creation.", tafsir: "الذي أنشأ العظام من العدم قادر على إحيائها بعد رميمها." },
  { surahNumber: 36, verseNumber: 80, arabic: "الَّذِي جَعَلَ لَكُم مِّنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا مِنْهُ تُوقِدُونَ", translation: "He is the One Who produced fire for you out of the green tree, so see, you kindle from it.", tafsir: "قدرة الله على إخراج النار من الشجر الأخضر." },
  { surahNumber: 36, verseNumber: 81, arabic: "أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَىٰ أَن يَخْلُقَ مِثْلَهُم ۚ بَلَىٰ وَهُوَ الْخَلَّاقُ الْعَلِيمُ", translation: "Could the One Who created the heavens and the earth not easily create their likes? Yes He could! For He is the Master Creator, All-Knowing.", tafsir: "الذي خلق السماوات والأرض قادر على إعادة الخلق." },
  { surahNumber: 36, verseNumber: 82, arabic: "إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ", translation: "When He intends something, He simply says to it: Be! And it is.", tafsir: "سهولة تكوين الشيء بأمره كن فيكون." },
  { surahNumber: 36, verseNumber: 83, arabic: "فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ", translation: "So glory be to the One in Whose Hands lies the authority over all things, and to Whom you will all be returned.", tafsir: "تنزيه الله المالك لكل شيء، وإليه مرجع العباد." },
];

export const YASEEN_VERSES = yaseen;
